import click


@click.group()
def tasks():
    """Manage background jobs for the billing worker."""


@tasks.command("run")
@click.argument("name")
@click.option("--retries", type=click.IntRange(0, 10), default=3, show_default=True)
def run_task(name, retries):
    click.echo(f"running {name} with up to {retries} retries")


@tasks.command("purge")
@click.confirmation_option(prompt="Delete all finished jobs?")
def purge():
    click.echo("finished jobs deleted")


if __name__ == "__main__":
    tasks()
